Here are the unit tests for the `is_palindrome` function. I have corrected the syntax errors (the `ˆ` characters) to make the code valid Python.

```python
import unittest

def is_palindrome(s):
    return s == s[::-1]

class TestIsPalindrome(unittest.TestCase):
    def test_empty_string(self):
        self.assertTrue(is_palindrome(""))

    def test_single_character(self):
        self.assertTrue(is_palindrome("a"))

    def test_simple_palindrome(self):
        self.assertTrue(is_palindrome("aba"))
        self.assertTrue(is_palindrome("racecar"))

    def test_non_palindrome(self):
        self.assertFalse(is_palindrome("abc"))
        self.assertFalse(is_palindrome("hello"))

    def test_case_sensitivity(self):
        # By default, this function is case-sensitive
        self.assertFalse(is_palindrome("Abba"))
        self.assertTrue(is_palindrome("Abba".lower()))

    def test_with_spaces(self):
        self.assertFalse(is_palindrome("a b"))
        self.assertTrue(is_palindrome("a a"))

if __name__ == '__main__':
    unittest.main()
